import{_ as t,o as a,a as s,a2 as r}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"AI in Bagisto","description":"","frontmatter":{},"headers":[],"relativePath":"ai/introduction.md","filePath":"ai/introduction.md","lastUpdated":1789319767000}'),o={name:"ai/introduction.md"};function i(n,e,l,c,d,h){return a(),s("div",null,e[0]||(e[0]=[r('<h1 id="ai-in-bagisto" tabindex="-1">AI in Bagisto <a class="header-anchor" href="#ai-in-bagisto" aria-label="Permalink to &quot;AI in Bagisto&quot;">​</a></h1><p>Bagisto ships with AI built in — both <strong>inside your store</strong> and <strong>inside your development workflow</strong>. This page is the home for everything AI-related: store features powered by AI, the hooks that let AI agents shop your store, and tools that make the AI agents <em>you</em> build with smarter about Bagisto.</p><div class="ai-cards__group-title">For your store</div><div class="ai-cards"><a class="ai-card" href="/ai/magic-ai.html"><div class="ai-card__title">✨ Magic AI</div><div class="ai-card__desc"> Generate product content &amp; images, image search, review translation and personalised checkout messages — powered by your choice of AI provider. </div></a><a class="ai-card" href="/ai/webmcp.html"><div class="ai-card__title">🤖 WebMCP</div><div class="ai-card__desc"> Storefront tools declared for browser AI agents, so an agent can search, open a product, manage the wishlist and reach checkout on a shopper&#39;s behalf. </div></a></div><div class="ai-cards__group-title">For developers &amp; AI agents</div><div class="ai-cards"><a class="ai-card" href="/ai/agent-skills.html"><div class="ai-card__title">🧩 Agent Skills</div><div class="ai-card__desc"> Pre-built skills that teach AI coding agents (Claude Code, Cursor, Windsurf) Bagisto&#39;s conventions so they generate correct packages, payment methods and themes. </div></a><a class="ai-card" href="/ai/llms-txt.html"><div class="ai-card__title">📄 llms.txt</div><div class="ai-card__desc"> Context files that help LLMs and AI tools understand Bagisto&#39;s architecture for more accurate, framework-aware suggestions. </div></a></div><h2 id="agentic-commerce" tabindex="-1">Agentic commerce <a class="header-anchor" href="#agentic-commerce" aria-label="Permalink to &quot;Agentic commerce&quot;">​</a></h2><p>&quot;Agentic commerce&quot; means two things for a store: the merchant&#39;s own work is assisted by AI, and the shopper may be an AI agent acting for a person. Bagisto covers both sides with features that are already in the core, and this section describes exactly what each one does rather than what it might grow into.</p><table tabindex="0"><thead><tr><th>Side</th><th>Feature</th><th>What it does today</th></tr></thead><tbody><tr><td>Merchant</td><td><a href="/ai/magic-ai.html">Magic AI</a></td><td>Writes and translates content, generates images, answers image searches, personalises the order confirmation</td></tr><tr><td>Shopper</td><td><a href="/ai/webmcp.html">WebMCP</a></td><td>Declares seven storefront actions to browsers that expose the WebMCP <code>navigator.modelContext</code> API, so an agent in the browser can act on the page</td></tr><tr><td>Developer</td><td><a href="/ai/agent-skills.html">Agent Skills</a>, <a href="/ai/llms-txt.html">llms.txt</a></td><td>Give coding agents Bagisto&#39;s conventions and architecture</td></tr></tbody></table><h2 id="magic-ai-—-built-into-your-store" tabindex="-1">Magic AI — built into your store <a class="header-anchor" href="#magic-ai-—-built-into-your-store" aria-label="Permalink to &quot;Magic AI — built into your store&quot;">​</a></h2><p><a href="/ai/magic-ai.html">Magic AI</a> is a first-class Bagisto feature. Add an API key for any supported provider and you can:</p><ul><li>✍️ <strong>Generate content</strong> — product descriptions, page copy, and more from the admin editor.</li><li>🖼️ <strong>Generate images</strong> — create product imagery from a text prompt.</li><li>🔍 <strong>Image search</strong> — let shoppers search your catalog by uploading a photo.</li><li>🌐 <strong>Translate reviews</strong> — show customer reviews in the shopper&#39;s language.</li><li>🎉 <strong>Checkout messages</strong> — personalised order confirmation messages.</li></ul><p>Magic AI works with <strong>OpenAI, Anthropic, Gemini, Groq, xAI, DeepSeek, Mistral, and Ollama</strong>. Admin features let you choose which providers are offered; storefront features are configured per channel with a model each.</p><h2 id="webmcp-—-let-agents-shop" tabindex="-1">WebMCP — let agents shop <a class="header-anchor" href="#webmcp-—-let-agents-shop" aria-label="Permalink to &quot;WebMCP — let agents shop&quot;">​</a></h2><p><a href="/ai/webmcp.html">WebMCP</a> is the browser-side counterpart. The storefront layout declares its search, product, wishlist, cart, checkout and newsletter actions as tools, and registers them with <code>navigator.modelContext.provideContext()</code> when the browser supports it. In every other browser the markup is inert. It is available on Bagisto 2.4 and the current development version alike.</p><h2 id="ai-for-developers" tabindex="-1">AI for developers <a class="header-anchor" href="#ai-for-developers" aria-label="Permalink to &quot;AI for developers&quot;">​</a></h2><p>Bagisto also helps the AI tools <em>you</em> code with:</p><ul><li><strong><a href="/ai/agent-skills.html">Agent Skills</a></strong> — install <code>bagisto/agent-skills</code> so your AI agent generates Bagisto-correct packages, payment methods, themes, and tests.</li><li><strong><a href="/ai/llms-txt.html">llms.txt</a></strong> — point Copilot, Cursor, ChatGPT, or Claude at Bagisto&#39;s context files for architecture-aware answers.</li></ul><div class="tip custom-block"><p class="custom-block-title">Where to start</p><p>Building a store? Start with <strong><a href="/ai/magic-ai.html">Magic AI</a></strong>. Letting agents shop it? Read <strong><a href="/ai/webmcp.html">WebMCP</a></strong>. Writing code? Install <strong><a href="/ai/agent-skills.html">Agent Skills</a></strong>.</p></div>',19)]))}const p=t(o,[["render",i]]);export{m as __pageData,p as default};
